#include <stdio.h>
#include <string.h>

void invertiStringa(char str[]) {
    int i = 0;
    int j = strlen(str) - 1;
    while (i < j) {
        char temp = str[i];
        str[i] = str[j];
        str[j] = temp;
        i++;
        j--;
    }
}

int main() {
    char testo[] = "Programmazione";
    printf("Stringa originale: %s\n", testo);
    invertiStringa(testo);
    printf("Stringa invertita: %s\n", testo);
    return 0;
}

