#include <stdio.h>

int isPrimo(int n) {
    if (n <= 1) return 0;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) return 0;
    }
    return 1;
}

int main() {
    int num;
    printf("Inserisci un numero intero positivo: ");
    scanf("%d", &num);
    if (isPrimo(num)) {
        printf("%d è un numero primo.\n", num);
    } else {
        printf("%d non è un numero primo.\n", num);
    }
    return 0;
}

#include <stdio.h>

void scambia(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

